import{_ as n,c as s,aU as l,a as e}from"./chunks/framework.DIXiA2XH.js";const u=JSON.parse('{"title":"工作辞退维权","description":"","frontmatter":{},"headers":[],"relativePath":"note/rights_protection/work.md","filePath":"note/rights_protection/work.md","lastUpdated":1773581595000}'),i={name:"note/rights_protection/work.md"};function r(p,a,t,o,c,h){return e(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="工作辞退维权" tabindex="-1">工作辞退维权 <a class="header-anchor" href="#工作辞退维权" aria-label="Permalink to &quot;工作辞退维权&quot;">​</a></h1><h2 id="线下投诉" tabindex="-1">线下投诉 <a class="header-anchor" href="#线下投诉" aria-label="Permalink to &quot;线下投诉&quot;">​</a></h2><ul><li>劳动监查大队</li><li>社保局</li><li>公积金中心</li><li>税务局</li></ul><h2 id="线上投诉" tabindex="-1">线上投诉 <a class="header-anchor" href="#线上投诉" aria-label="Permalink to &quot;线上投诉&quot;">​</a></h2><ul><li>12333小程序 人力资源和社会保障局的电话</li><li>国家税务总局网站</li><li>欠薪线索劳动维权平台</li><li>黑猫投诉</li><li>国务院客户端</li></ul><h2 id="投诉类型" tabindex="-1">投诉类型 <a class="header-anchor" href="#投诉类型" aria-label="Permalink to &quot;投诉类型&quot;">​</a></h2><ul><li>违反劳动法</li><li>偷税漏税</li><li>非法经营</li></ul><h2 id="公司最忌惮的讨薪手段" tabindex="-1">公司最忌惮的讨薪手段 <a class="header-anchor" href="#公司最忌惮的讨薪手段" aria-label="Permalink to &quot;公司最忌惮的讨薪手段&quot;">​</a></h2><p>通过个人所得税app向税务机关发起申诉，薪酬问题，直接关联个税申报，一旦申诉成立，税务部门将迅速介入 ，并且联系企业，为了避免影响信用评级和正常的运营，企业通常会立刻主动联系申诉人撤销申诉，这个时候你就要表态， 撤诉前企业一定要一次性的结清全部拖欠的薪资以及赔偿。</p><h2 id="拒绝待岗通知" tabindex="-1">拒绝待岗通知 <a class="header-anchor" href="#拒绝待岗通知" aria-label="Permalink to &quot;拒绝待岗通知&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>XX公司：</span></span>
<span class="line"><span>    公司于2024年x月x日对我(XXX，身份证号:xxx）发出口头待岗通知，但公司要求本人待岗是公司的违法行为，为此本人不同意公司的待岗安排。</span></span>
<span class="line"><span>拒绝理由如下：</span></span>
<span class="line"><span>1、公司此次发出的待岗通知，是因本人未同意变相降薪而采取的违法行为；</span></span>
<span class="line"><span>2、公司本次待岗通知是针对我个人的，是有针对性和惩罚性的，并不是全部门或全员待岗；</span></span>
<span class="line"><span>3、公司并未向本人提供公司生产经营已无法开展的证据证明；</span></span>
<span class="line"><span>4、《劳动合同法》第十二条，非因劳动者原因造成单位停工、停产在一个工资支付周期内的，用人单位应按劳动合同规定的标准支付劳动者工资；</span></span>
<span class="line"><span>5、公司本次的待岗通知并未注明返岗时间。</span></span>
<span class="line"><span>员工</span></span>
<span class="line"><span>联系电话</span></span>
<span class="line"><span>日期</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h2 id="法律条文" tabindex="-1">法律条文 <a class="header-anchor" href="#法律条文" aria-label="Permalink to &quot;法律条文&quot;">​</a></h2><p>《中华人民共和国劳动合同法》第四十七条 第四十七条 经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。 “+1”是指代通知金，即用人单位没有提前30天书面通知你解除合同，就需要额外支付1个月工资作为替代。</p><h2 id="投诉追缴公积金" tabindex="-1">投诉追缴公积金 <a class="header-anchor" href="#投诉追缴公积金" aria-label="Permalink to &quot;投诉追缴公积金&quot;">​</a></h2><p><strong>需要的材料如下：</strong></p><ol><li>身份证原件和复印件</li><li>工资流水明细</li><li>个税缴纳明细</li><li>社保缴纳明细</li><li>劳动合同或者离职证明</li></ol><p><strong>如果公积金追缴受理很慢怎么办？（网友推荐的方法）</strong></p><ul><li>国家信访局举报</li><li>市长热线打电话投诉公积金推进慢</li></ul>`,18)])])}const b=n(i,[["render",r]]);export{u as __pageData,b as default};
